import{_ as o,o as e,c as a,a2 as t}from"./chunks/framework.DdtnLau3.js";const h=JSON.parse('{"title":"Work","description":"","frontmatter":{},"headers":[],"relativePath":"zh/concepts/work.md","filePath":"zh/concepts/work.md"}'),s={name:"zh/concepts/work.md"};function i(n,r,l,k,p,c){return e(),a("div",null,[...r[0]||(r[0]=[t('<h1 id="work" tabindex="-1">Work <a class="header-anchor" href="#work" aria-label="Permalink to &quot;Work&quot;">​</a></h1><p><strong>Work 封装一个可运行的工作空间</strong>。在 Piwork 中，你为它命名，并对它执行启动、停止、导出和导入。</p><p>例如，一个 Kanban Work 可以包含看板应用、已保存的数据、操作工具、Harness 指令，以及共同修改应用的历史。这些资源放在一起，才能构成可以继续使用的环境。</p><h2 id="work-包含什么" tabindex="-1">Work 包含什么？ <a class="header-anchor" href="#work-包含什么" aria-label="Permalink to &quot;Work 包含什么？&quot;">​</a></h2><ul><li>工作空间文件、源码和托管卷中的应用数据。</li><li>Service 定义和固定容器镜像。</li><li>Harness 配置、<code>AGENTS.md</code>、Skills 和 Pi Packages。</li><li>对话历史和持久控制历史。</li><li>恢复工作空间所需的当前、期望和保留配置。</li></ul><p>Agent 有私有数据卷，以及位于 <code>/var/data/workspace</code> 的共享工作空间。配置允许时，Services 可以共享该目录。希望携带的数据需要保存在托管存储中；容器临时文件不在可携带边界内。</p><h2 id="运行和修改" tabindex="-1">运行和修改 <a class="header-anchor" href="#运行和修改" aria-label="Permalink to &quot;运行和修改&quot;">​</a></h2><p>启动 Work 会运行 Harness 并恢复已启用的 Services。停止后，持久文件、历史和定义仍然保留。</p><p>部分配置修改会形成<strong>期望配置（desired）</strong>，需要显式 <strong>Apply</strong> 才会生效。已保存的配置与当前 Harness 加载的运行配置需要区分。</p><h2 id="移动-work" tabindex="-1">移动 Work <a class="header-anchor" href="#移动-work" aria-label="Permalink to &quot;移动 Work&quot;">​</a></h2><p><strong>停止 → 导出 → 分享 → 导入 → 启动 → 继续</strong></p><p>导出从已停止的 Work 生成 <code>.work</code> 归档。导入会创建一个独立的新 Work，分配新的平台身份，并保持停止状态。准备好后再启动。</p><p>归档携带固定镜像内容和持久工作空间状态，不携带活进程内存或 Piwork 之外的服务。接收方需要单独配置兼容的模型和凭据。</p><p>文件和历史按原内容复制，不过滤用户内容。分享前检查保存过的内容：写在源码或对话里的密钥，也会随 Work 移动。</p><p>实际命令见<a href="/piwork/zh/guide/first-work.html">第一个 Work</a>，格式细节见 <a href="/piwork/zh/spec/work.html">Work 包规范</a>。</p>',15)])])}const _=o(s,[["render",i]]);export{h as __pageData,_ as default};
